'use strict';
let connectionAttempt=null;
function startConnection(channel){if(!canPublish()||!channelCatalog.some(c=>c.id===channel)||(channel==='hashnode'&&workspaceKind()==='personal'))return false;connectionAttempt={id:nextWorkflowId('connection'),owner:state.workspace,channel,account:connectionMeta[state.workspace][channel].account,previous:connectionStates[state.workspace][channel],status:'pending'};connectionStates[state.workspace][channel]='pending';return true;}
function finishConnection(result,attemptId=connectionAttempt?.id){const a=connectionAttempt;if(!a||a.id!==attemptId||a.status!=='pending'||a.owner!==state.workspace||!canPublishOwner(a.owner))return false;const states={success:'connected',cancel:a.previous==='pending'?'unconfigured':a.previous,failure:'expired',unbound:'unbound',mismatch:'mismatch'};if(!Object.hasOwn(states,result))return false;connectionStates[a.owner][a.channel]=states[result];a.status=result;if(result==='success')connectionMeta[a.owner][a.channel].verifiedAt=nowStamp();return true;}
connectionsPage=function(){if(!canPublish())return titleBlock('CONNECTED, WITH CLARITY','连接与渠道',txt('仅 Publisher 可查看当前工作区的私有连接。','Only Publishers may view private connections for this workspace.'))+emptyState(txt('连接信息不可访问','Connection details are restricted'),txt('可继续创作和提交自己的内容。','You can continue writing and submitting your own content.'),routeButton('返回内容库','content'));return titleBlock('CONNECTED, WITH CLARITY','连接与渠道',txt('每个平台都需要核验当前工作区的指定账号，包括人工投稿渠道。','Every platform requires a verified designated account for this workspace, including assisted channels.'))+notice(txt('当前为连接交互原型。真实绑定与账号回执仍需服务端集成；演示不会打开真实授权或收集凭据。','This is a connection-flow prototype. Real binding and account receipts still require backend integration. The demo never opens real authorization or collects credentials.'))+`<div class="connection-grid">${channelCatalog.map(c=>{const m=connectionMeta[state.workspace][c.id],s=connectionStates[state.workspace][c.id];return `<section class="panel connection-card"><div class="channel-head">${platform(c.id)}<div class="channel-name"><strong>${c.name}</strong><small>${esc(workspaceLabel())}</small></div>${statusBadge(s)}</div><p>${c.summary}</p><div class="connection-facts"><span>${txt('指定账号','Designated account')}</span><strong>${esc(m.account)}</strong><span>${txt('核验时间','Last verified')}</span><strong>${m.verifiedAt||'—'}</strong></div>${s==='unsupported'?notice(txt('个人 Hashnode 暂不支持。','Personal Hashnode is not supported.')):canPublish()?flowButton('管理连接','Manage connection','channel-connect',c.id,'full'):notice(txt('当前身份只读；Publisher 可管理指定连接。','Read only for this role. A Publisher can manage designated connections.'))}</section>`;}).join('')}</div>`;};pageRenderers.connections=connectionsPage;
showChannel=function(id){if(!canPublish())return;const c=channelCatalog.find(c=>c.id===id);if(!c)return;site.channel=id;const s=connectionStates[state.workspace][id],m=connectionMeta[state.workspace][id];modal(c.name+' · '+txt('工作区连接','Workspace connection'),`<div class="connection-flow"><span>01 · ${txt('核对工作区','Check workspace')}</span><span>02 · NyxID</span><span>03 · ${txt('回到 CMS 核验','Return & verify')}</span></div><div class="review-line"><span>${txt('内容所有者','Content owner')}</span><strong>${esc(workspaceLabel())}</strong></div><div class="review-line"><span>${txt('指定账号','Designated account')}</span><strong>${esc(m.account)}</strong></div><div class="review-line"><span>${txt('连接状态','Connection state')}</span>${statusBadge(s)}</div><p>${txt('恢复连接不会重发内容，也不会重置已有任务。返回后须确认账号归属和绑定状态。','Restoring a connection never resends content or resets existing tasks. Account ownership and binding are checked on return.')}</p>${s==='unbound'?notice(txt('NyxID 已完成连接，但 CMS 尚未取得对应绑定；确认映射后再重新核验。','NyxID is connected, but the CMS binding is not available yet. Confirm the mapping and verify again.')):''}${s==='mismatch'?notice(txt('返回账号不属于当前工作区，已阻止使用。请重新选择正确账号。','The returned account does not belong to this workspace and has been blocked. Choose the correct account.')):''}`,btn('关闭','close-modal')+(s!=='unsupported'&&canPublish()?flowButton(s==='connected'?'重新核验指定连接':'前往 NyxID · 演示',s==='connected'?'Recheck designated connection':'Continue to NyxID · demo','connection-start',id,'primary')+flowButton('演示连接失效','Simulate expiry','connection-expire',id,'quiet'):''));};
flowHandlers['connection-expire']=id=>{if(canPublish()){connectionStates[state.workspace][id]='expired';closeModal();render();}};
flowHandlers['connection-start']=id=>{if(!startConnection(id))return;modal('NyxID · '+txt('连接回跳演示','Connection return demo'),`<div class="connection-identity">${mark}<div><strong>${esc(workspaceLabel(connectionAttempt.owner))}</strong><p>${channelName(id)} · ${esc(connectionAttempt.account)}</p></div></div><p>${txt('本地演示：选择一次返回结果，检查 CMS 如何处理连接和绑定。','Local demo: choose a return result to see how the CMS handles connection and binding.')}</p><div class="demo-control-grid">${flowButton('连接成功并绑定','Connected & bound','connection-result',connectionAttempt.id+':success')}${flowButton('已连接但未绑定','Connected, not bound','connection-result',connectionAttempt.id+':unbound')}${flowButton('返回失败','Return failed','connection-result',connectionAttempt.id+':failure')}${flowButton('账号归属不匹配','Wrong account owner','connection-result',connectionAttempt.id+':mismatch')}</div>`,flowButton('取消授权','Cancel authorization','connection-result',connectionAttempt.id+':cancel'));};
flowHandlers['connection-result']=value=>{const [attemptId,result]=value.split(':');const channel=connectionAttempt?.channel;if(!finishConnection(result,attemptId)){closeModal();render();toast(txt('工作区或权限已变化，未接受该返回。','The workspace or permission changed; the return was not accepted.'));return;}closeModal();render();showChannel(channel);};
actions['connect-channel']=()=>flowHandlers['connection-start'](site.channel);
actions['expire-channel']=()=>flowHandlers['connection-expire'](site.channel);

const closeConnectionModal=closeModal;closeModal=function(){if(connectionAttempt?.status==='pending'){const a=connectionAttempt;connectionStates[a.owner][a.channel]=a.previous;a.status='cancel';}closeConnectionModal();};
